import yaml from 'js-yaml';
import { encode } from 'gpt-tokenizer';
import { FigmaCompressor } from './compressor.js';
function cleanNodeForYaml(node, isRoot = false) {
    const clean = {};
    const isRedundantTextName = !isRoot &&
        node.type === 'text' &&
        !!node.name &&
        !!node.text &&
        node.name.trim() === node.text.trim();
    if (node.name && !isRedundantTextName) {
        clean.name = node.name;
    }
    if (node.type && node.type !== 'frame') {
        clean.type = node.type;
    }
    if (node.classes) {
        clean.classes = node.classes;
    }
    if (node.text !== undefined) {
        clean.text = node.text;
    }
    if (node.icon !== undefined) {
        clean.icon = node.icon;
    }
    if (node.image !== undefined) {
        clean.image = node.image;
    }
    if (node.repeatCount !== undefined) {
        clean.repeatCount = node.repeatCount;
    }
    if (node.children && Array.isArray(node.children) && node.children.length > 0) {
        clean.children = node.children.map(child => cleanNodeForYaml(child, false));
    }
    return clean;
}
export function serializeToYaml(spec) {
    const yamlObj = cleanNodeForYaml(spec, true);
    return yaml.dump(yamlObj, {
        indent: 2,
        noRefs: true,
        lineWidth: -1,
        skipInvalid: true
    });
}
export function generateAgentPrompt(specYaml, componentName = 'Component') {
    return `# Figma-to-Code Specification: ${componentName}

> Optimized compact AST generated by figma-spec-compressor
> Use this spec to generate high-fidelity React + Tailwind CSS code.

## Component Implementation Instructions
1. Follow the component tree structure exactly as outlined in the YAML specification.
2. Use the provided Tailwind utility classes for layout, flex directions, padding, colors, and shadows.
3. Replace icon nodes with appropriate Lucide React icons matching their names.
4. Keep the output clean, accessible (semantic HTML), and modular.

\`\`\`yaml
${specYaml.trim()}
\`\`\`
`;
}
export function processAndBenchmark(rawFigma, options) {
    const compressor = new FigmaCompressor(options);
    const spec = compressor.compress(rawFigma);
    if (!spec) {
        throw new Error('Failed to compress Figma node: Root node resulted in null.');
    }
    const specYaml = serializeToYaml(spec);
    const markdown = generateAgentPrompt(specYaml, spec.name || rawFigma.name || 'Component');
    const rawJsonStr = JSON.stringify(rawFigma);
    const rawJsonBytes = Buffer.byteLength(rawJsonStr, 'utf-8');
    const yamlBytes = Buffer.byteLength(specYaml, 'utf-8');
    // Exact BPE token calculation via gpt-tokenizer
    const rawTokens = encode(rawJsonStr).length;
    const compressedTokens = encode(specYaml).length;
    const reductionPercentage = rawTokens > 0 ? Math.round((1 - compressedTokens / rawTokens) * 100) : 0;
    return {
        spec,
        yaml: specYaml,
        markdown,
        metrics: {
            rawNodesCount: compressor.rawNodeCount,
            cleanNodesCount: compressor.cleanNodeCount,
            rawJsonBytes,
            yamlBytes,
            rawTokens,
            compressedTokens,
            rawTokensEstimate: rawTokens,
            compressedTokensEstimate: compressedTokens,
            reductionPercentage
        }
    };
}
